#!/usr/bin/env python3
"""Retain bounded public-family runs and regenerate complete, identity-bound Singular references."""
import argparse
import gzip
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import signal
import subprocess
import time

ROOT = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location('mq10_profile', Path(__file__).with_name('mq10-profile.py'))
guard = importlib.util.module_from_spec(spec)
spec.loader.exec_module(guard)


def write(path, data):
    temporary = path.with_name(path.name + '.tmp')
    temporary.write_bytes(gzip.compress((json.dumps(data, indent=2) + '\n').encode(), mtime=0))
    temporary.replace(path)


def regenerate(attempts):
    if len(attempts) != 6 or len({a['report']['name'] for a in attempts}) != 6:
        raise ValueError('reference regeneration needs all six distinct cases exactly once')
    rows, pending = [], []
    for a in attempts:
        r = a['report']
        if r['engine'] != 'singular' or r['status'] != 'complete' or '44105' not in r['version']:
            raise ValueError('reference generation requires complete Singular build 44105 answers')
        if r['modulus'] != 32003 or hashlib.sha256(r['canonical'].encode()).hexdigest() != r['digest']:
            raise ValueError('reference input identity mismatch')
        if not r['basis'] or r['quotient_dimension'] is None:
            raise ValueError('selected public case needs a nonempty finite reference')
        basis = '\n'.join(sorted(r['basis'])) + '\n'
        path = ROOT / 'src/grobner/external/public_corpus_references' / (r['name'] + '.basis')
        pending.append((path, basis))
        rows.append('    PublicCase { name: "%s", family: "%s", variables: %s, tier: Tier::%s, digests: &[(32003,"%s")], basis_sha256: "%s", quotient_dimension: %s, basis: include_str!("public_corpus_references/%s.basis") },' %
                    (r['name'], r['family'], len(r['variables']), r['tier'], r['digest'], hashlib.sha256(basis.encode()).hexdigest(), r['quotient_dimension'], r['name']))
    for path, basis in pending:
        path.write_text(basis)
    (ROOT / 'src/grobner/external/public_corpus_cases.rs').write_text(
        '// Generated by tools/external/public-corpus.py --regenerate; references bind the complete ring and input.\n&[\n' + '\n'.join(rows) + '\n]\n')


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--binary', type=Path, required=True)
    parser.add_argument('--scratch', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--engines', default='singular,zeebra,grobx')
    parser.add_argument('--repeats', type=int, default=3)
    parser.add_argument('--regenerate', action='store_true')
    parser.add_argument('--build', required=True, help='exact build profile/ISA settings for the supplied executable')
    args = parser.parse_args()
    engines = args.engines.split(',')
    if args.repeats < 1 or (args.regenerate and (engines != ['singular'] or args.repeats != 1)):
        parser.error('regeneration requires --engines singular --repeats 1; repeats must be positive')
    if not os.environ.get('ZEEBRA_MACHINE'):
        parser.error('set ZEEBRA_MACHINE and launch under benchlock with explicit CPU affinity')
    affinity = ','.join(str(i) for i in sorted(os.sched_getaffinity(0)))
    if affinity != os.environ.get('ZEEBRA_AFFINITY'):
        parser.error('ZEEBRA_AFFINITY must equal the actual comma-separated CPU set')
    args.scratch.mkdir(parents=True, exist_ok=True)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    cases = json.loads(subprocess.check_output([str(args.binary), '--list'], text=True))
    cohort = dict(schema=1, commit=subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(),
                  tracked_diff_sha256=hashlib.sha256(subprocess.check_output(['git', 'diff', 'HEAD'], cwd=ROOT)).hexdigest(),
                  binary_sha256=hashlib.sha256(args.binary.read_bytes()).hexdigest(), build=args.build,
                  rustc=subprocess.check_output(['rustc', '-vV'], text=True),
                  machine=os.environ['ZEEBRA_MACHINE'], affinity=affinity, workers=1,
                  policy='one case/engine per process; 60s/2GiB solver limits, 185s/2GiB complete process-tree watchdog; retain every refusal',
                  cases=cases, attempts=[])
    for repeat in range(args.repeats):
        for c in cases:
            for engine in (engines if repeat % 2 == 0 else engines[::-1]):
                stem = args.scratch / str(len(cohort['attempts']))
                command = [str(args.binary), '--row', c['name'], '--engine', engine]
                if args.regenerate:
                    command.append('--reference-generation')
                started, peak, stop = time.monotonic_ns(), 0, None
                with stem.with_suffix('.stdout').open('w') as out, stem.with_suffix('.stderr').open('w') as err:
                    process = subprocess.Popen(command, stdout=out, stderr=err, start_new_session=True)
                    while process.poll() is None:
                        peak = max(peak, guard.tree_hwm(process.pid))
                        if peak > 2*1024**3 or time.monotonic_ns()-started > 185_000_000_000:
                            stop = 'rss' if peak > 2*1024**3 else 'wall'
                            os.killpg(process.pid, signal.SIGKILL)
                            process.wait()
                            break
                        time.sleep(0.002)
                a = dict(repeat=repeat, name=c['name'], engine=engine, exit=process.returncode, stop=stop,
                         process_wall_ns=time.monotonic_ns()-started, observed_tree_peak_bytes=peak,
                         stderr=stem.with_suffix('.stderr').read_text())
                if process.returncode == 0:
                    a['report'] = json.loads(stem.with_suffix('.stdout').read_text())
                    if a['report']['digest'] != c['digest']:
                        raise ValueError('runner changed input identity')
                cohort['attempts'].append(a)
                write(args.output, cohort)
                print(repeat, c['name'], engine, a.get('report', {}).get('status', 'runner-failure'), flush=True)
                if args.regenerate and (process.returncode != 0 or a['report']['status'] != 'complete'):
                    raise RuntimeError('oracle did not complete; attempt retained')
    if args.regenerate:
        regenerate(cohort['attempts'])


if __name__ == '__main__':
    main()
